-- Тематическая замена английских карточек: 300 RU→EN и 400 EN→RU.
-- Слова/названия — данные поставки, Java-движок и API не меняются.
-- Старые банки, версии, снимки, ответы и результаты остаются неизменными.
-- Наборы явно UNIVERSAL; cross-set выключен. KK-банк не затрагивается.
-- Системная публикация имеет actor_id/reviewed_by=NULL, без фиктивных аккаунтов.
-- Числа сложности 2/3 — внутренняя шкала банка, не сертифицированный уровень CEFR.
create table quiz_v59_banks (
    code varchar(96) primary key, source_language varchar(8), target_language varchar(8),
    title_ru varchar(255),title_kk varchar(255),description_ru text,description_kk text,catalog_order integer
);
-- Коллизия нового кода отклоняет поставку до первой записи в рабочие таблицы.
create table quiz_v59_guard (valid boolean not null check(valid=true));
select not exists(select 1 from quiz_v59_banks b join vocabulary_sets s on lower(s.code)=lower(b.code))
   and not exists(select 1 from quiz_v59_banks b join quiz_games g on lower(g.code)=lower(b.code));

create table quiz_v59_words (
    code varchar(96),word_no integer,english varchar(512),source_text varchar(512),source_normalized varchar(512),
    part_of_speech varchar(64),difficulty integer,meaning_note_ru text,source_reference text,
    primary key(code,word_no),unique(code,source_normalized)
);
create table quiz_v59_answers (
    code varchar(96),word_no integer,answer_text varchar(512),answer_normalized varchar(512),
    is_primary boolean,primary_marker integer,unique(code,word_no,answer_normalized)
);
create table quiz_v59_exclusions (code varchar(96),first_word varchar(512),second_word varchar(512),reason text);

select code,source_language,target_language,'PUBLISHED' from quiz_v59_banks;
select s.id,1,'PUBLISHED',b.title_ru,b.title_kk,'https://dictionary.cambridge.org/dictionary/english-russian/',false,current_timestamp,current_timestamp
from quiz_v59_banks b join vocabulary_sets s on s.code=b.code;
update vocabulary_sets set published_version_id=(select v.id from vocabulary_set_versions v where v.set_id=vocabulary_sets.id)
where code in(select code from quiz_v59_banks);

select s.id,'PUBLISHED' from quiz_v59_words w join vocabulary_sets s on s.code=w.code;
-- ID назначает БД. Порядковые номера связывают только что созданные пустые записи с 50 словами
-- своего нового набора; это не изменение ID или содержимого существующих учебных значений.
create table quiz_v59_item_ids (id bigint primary key,code varchar(96),word_no integer);
select i.id,s.code,row_number() over(partition by s.id order by i.id)
from vocabulary_items i join vocabulary_sets s on s.id=i.set_id join quiz_v59_banks b on b.code=s.code;
     source_reference,universal_audience,reviewed_at,published_at)
select m.id,1,'PUBLISHED',w.source_text,w.source_normalized,w.part_of_speech,w.difficulty,w.meaning_note_ru,
       w.source_reference,true,current_timestamp,current_timestamp
from quiz_v59_item_ids m join quiz_v59_words w on w.code=m.code and w.word_no=m.word_no;
select v.id,a.answer_text,a.answer_normalized,a.is_primary,a.primary_marker
from quiz_v59_item_ids m join vocabulary_item_versions v on v.item_id=m.id
join quiz_v59_answers a on a.code=m.code and a.word_no=m.word_no;
update vocabulary_items set published_version_id=(select v.id from vocabulary_item_versions v where v.item_id=vocabulary_items.id)
where id in(select id from quiz_v59_item_ids);

-- Синонимы и пересекающиеся значения не становятся ошибочными ответами даже при разных строках.
select va.id,vb.id,e.reason from quiz_v59_exclusions e
join quiz_v59_words a on a.code=e.code and a.english=e.first_word
join quiz_v59_words b on b.code=e.code and b.english=e.second_word
join quiz_v59_item_ids ma on ma.code=a.code and ma.word_no=a.word_no
join quiz_v59_item_ids mb on mb.code=b.code and mb.word_no=b.word_no
join vocabulary_item_versions va on va.item_id=ma.id join vocabulary_item_versions vb on vb.item_id=mb.id;

select code,'PUBLISHED',true from quiz_v59_banks;
     mechanic_label_ru,mechanic_label_kk,card_style,catalog_order,audience_policy,grade_selection_mode,
     min_question_count,default_question_count,max_question_count,min_round_seconds,default_round_seconds,
     max_round_seconds,question_count_editable,round_seconds_editable,max_players,reviewed_at,published_at)
select g.id,1,'WORD_TRANSLATION','PUBLISHED',b.title_ru,b.title_kk,b.description_ru,b.description_kk,
       'Выберите перевод','Аударманы таңдаңыз','english',b.catalog_order,'UNIVERSAL','NONE',
       5,10,30,5,20,60,true,true,4,current_timestamp,current_timestamp
from quiz_v59_banks b join quiz_games g on g.code=b.code;
select v.id,s.id,s.source_language,s.target_language from quiz_v59_banks b
join quiz_games g on g.code=b.code join quiz_game_versions v on v.game_id=g.id
join vocabulary_sets s on s.code=b.code;
update quiz_games set published_version_id=(select v.id from quiz_game_versions v where v.game_id=quiz_games.id),admin_revision=1
where code in(select code from quiz_v59_banks);

select 'VOCABULARY_SET',s.id,v.id,'DRAFT','PUBLISHED' from quiz_v59_banks b
join vocabulary_sets s on s.code=b.code join vocabulary_set_versions v on v.set_id=s.id;
select 'VOCABULARY_ITEM',m.id,v.id,'DRAFT','PUBLISHED' from quiz_v59_item_ids m
join vocabulary_item_versions v on v.item_id=m.id;
select 'GAME',g.id,v.id,'DRAFT','PUBLISHED' from quiz_v59_banks b
join quiz_games g on g.code=b.code join quiz_game_versions v on v.game_id=g.id;

-- Заменяются только две прежние английские карточки с их собственными банками.
-- Их настройки и версии сохраняются; активные/завершённые комнаты продолжают читать снимки.
create table quiz_v59_hidden (game_id bigint primary key);
select g.id from quiz_games g join quiz_game_versions v on v.id=g.published_version_id
join quiz_word_game_configs c on c.game_version_id=v.id join vocabulary_sets s on s.id=c.vocabulary_set_id
where g.code in('basic-ru-en-300-v1','basic-en-ru-400-v1') and s.code=g.code
  and g.catalog_visible=true and g.status<>'ARCHIVED';
select game_id,false from quiz_v59_hidden;
update quiz_games set catalog_visible=false,visibility_updated_by=null,visibility_updated_at=current_timestamp,
    updated_at=current_timestamp,admin_revision=admin_revision+1 where id in(select game_id from quiz_v59_hidden);

drop table quiz_v59_hidden;
drop table quiz_v59_item_ids;
drop table quiz_v59_exclusions;
drop table quiz_v59_answers;
drop table quiz_v59_words;
drop table quiz_v59_guard;
drop table quiz_v59_banks;
